__global__ void affine(const float* x,float* y,float a,float b,int n){int i=blockIdx.x*blockDim.x+threadIdx.x;if(i<n)y[i]=a*x[i]+b;}
int main(){const int N=1<<24,NS=4,chunk=1<<20;size_t bytes=N*4;float *hIn,*hOut;CUDA_CHECK(cudaMallocHost(&hIn,bytes));CUDA_CHECK(cudaMallocHost(&hOut,bytes));for(int i=0;i<N;i++)hIn[i]=i*.001f;std::vector<cudaStream_t>streams(NS);std::vector<float*>dIn(NS),dOut(NS);for(int s=0;s<NS;s++){CUDA_CHECK(cudaStreamCreate(&streams[s]));CUDA_CHECK(cudaMalloc(&dIn[s],chunk*4));CUDA_CHECK(cudaMalloc(&dOut[s],chunk*4));}for(int off=0,job=0;off<N;off+=chunk,job++){int s=job%NS,n=std::min(chunk,N-off);CUDA_CHECK(cudaStreamSynchronize(streams[s]));CUDA_CHECK(cudaMemcpyAsync(dIn[s],hIn+off,n*4,cudaMemcpyHostToDevice,streams[s]));affine<<<(n+255)/256,256,0,streams[s]>>>(dIn[s],dOut[s],1.25f,-3.0f,n);check_kernel("affine");CUDA_CHECK(cudaMemcpyAsync(hOut+off,dOut[s],n*4,cudaMemcpyDeviceToHost,streams[s]));}CUDA_CHECK(cudaDeviceSynchronize());for(int i=0;i<N;i+=7919)if(!nearly_equal(hOut[i],1.25f*hIn[i]-3,1e-3f,1e-5f))return 1;for(int s=0;s<NS;s++){CUDA_CHECK(cudaFree(dIn[s]));CUDA_CHECK(cudaFree(dOut[s]));CUDA_CHECK(cudaStreamDestroy(streams[s]));}CUDA_CHECK(cudaFreeHost(hIn));CUDA_CHECK(cudaFreeHost(hOut));std::cout<<"PASS\n";}
